	interface TraceHandle : AutoCloseable {
		Trace getTrace();

		Tx startTx();

		void addLotsOfRegions()
    {
			using (Tx tx = startTx())
{
				AddressFactory af = getTrace().getBaseAddressFactory();
				AddressSpace space = af.getDefaultAddressSpace();
				for (int i = 0; i < REGION_COUNT; i++) {
					AddressRange range = new AddressRangeImpl(space.getAddress(i * 1024), 1024);
					addRegion(Integer.toString(i), range, "rw");
				}
			}
		}

		void addRegion(string key, AddressRange range, string perms);
	}

