					.toList());
			return addPlugin(tool, typeof(NerfedTraceRmiPlugin));
		}
	}

	static class TimeMe : AutoCloseable {
		private string name;
		private long start;

		public TimeMe(string name) {
			this.name = name;
			Msg.info(this, "Starting: " + name);
			this.start = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
		}

		/* @Override */
		public void close()
    {
			long elapsed = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - start;
			Msg.info(this, "Finished: " + name + ". Took " + elapsed + " ms");
		}
	}

