	static class NerfedTraceRmiAcceptor : DefaultTraceRmiAcceptor {
		public NerfedTraceRmiAcceptor(TraceRmiPlugin plugin, SocketAddress address) : base(plugin, address)
    {
		}

		/* @Override */
		public NerfedTraceRmiHandler doAccept(TraceRmiAcceptor acceptor)
    {
			Socket client = socket.accept();
			NerfedTraceRmiHandler handler = new NerfedTraceRmiHandler(plugin, client);
			handler.start();
			plugin.listeners.invoke().connected(handler, getConnectMode(), acceptor);
			return handler;
		}
	}

	public static class NerfedTraceRmiPlugin : TraceRmiPlugin {
		public NerfedTraceRmiPlugin(PluginTool tool) : base(tool)
    {
		}

		/* @Override */
		public DefaultTraceRmiAcceptor acceptOne(SocketAddress address)
    {
			NerfedTraceRmiAcceptor acceptor = new NerfedTraceRmiAcceptor(this, address);
			acceptor.start();
			listeners.invoke().waitingAccept(acceptor);
			return acceptor;
		}
	}

